// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(string memory description) public {
        // Admissible caller: only the jojoTeam account can pass the onlyJojoTeam modifier.
        address caller = c.jojoTeam();
        vm.prank(caller);
        c.newEmergencyOracle(description);

        // The very first contract created by c is the new EmergencyOracle.
        address oracle = computeCreateAddress(address(c), 1);

        // General rule: the freshly created oracle's owner is the calling account.
        (bool ok, bytes memory ret) = oracle.staticcall(abi.encodeWithSignature("owner()"));
        assertTrue(ok && abi.decode(ret, (address)) == caller);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        // Admissible domain: any caller; zero caller is allowed so the
        // zero-ownership edge of the JOJO team is exercised.
        address jt = c.jojoTeam();

        bool ok;
        vm.prank(actor);
        try c.newEmergencyOracle("fuzz-description") {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: the oracle creation succeeds for a caller if and only
        // if the caller is the JOJO team AND the JOJO team address is nonzero
        // (so the ownership hand-off inside the new oracle can succeed).
        assertTrue(ok == (actor == jt && jt != address(0)));
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(string calldata description) public {
        require(msg.sender != c.jojoTeam(), "test must be called by a non-team address");
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.newEmergencyOracle.selector, description));
        assert(!ok);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(string calldata description) public {
        // jojoTeam has no setter and is initially address(0); this caller is not the JOJO team,
        // so on P the access check must revert the call.
        bool ok;
        (ok, ) = address(c).call(abi.encodeWithSelector(C.newEmergencyOracle.selector, description));
        assert(!ok);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        require(true);
        bool reverted; try c.newEmergencyOracle("test description") { reverted = false; } catch { reverted = true; }
        assert(reverted == (msg.sender != c.jojoTeam()));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string calldata description) public {
        require(true);
        bool reverted;
        c.newEmergencyOracle(description);
        reverted = false;
        assert(reverted == (c.jojoTeam() != address(this)));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(string calldata description) public {
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(c.newEmergencyOracle.selector, description)
        );
        assert(!ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        require(msg.sender != c.jojoTeam(), "caller is the jojo team; rule not applicable");
        bool reverted;
        try c.newEmergencyOracle("test") { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string calldata description) public payable {
        require(true);
        bool reverted;
        try c.newEmergencyOracle(description) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string calldata description) public payable {
        require(true);
        bool reverted;
        c.newEmergencyOracle(description);
        assert(msg.sender == c.jojoTeam());
    }
    receive() external payable { }
}
